13	// sys.stdout as the program set it (`sys.stdout = io.StringIO()`, as test.support.captured_output does): None while
14	// it is the real stream. print() and input() write to it, and reading sys.stdout gives it back, as in CPython.
15	// Only for programs that run nothing in CPython: a bridged library would still print to the real stream.
16	thread_local! {
17	    pub static STDOUT_SET: RefCell<Option<V>> = const { RefCell::new(None) };
18	}
19	static BRIDGED_RUN: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
20	pub fn set_bridged() {
21	    BRIDGED_RUN.store(true, std::sync::atomic::Ordering::Relaxed);
22	}
23	pub fn stdout_set() -> Option<V> {
24	    STDOUT_SET.with(|s| s.borrow().clone())
25	}
26	pub fn sys_stream_assign(name: &str, v: V) -> Result<(), E> {
27	    match name {
28	        "stdout" => {
29	            if BRIDGED_RUN.load(std::sync::atomic::Ordering::Relaxed) {
30	                return Err(unsupported("assigning sys.stdout in a program that runs a library in CPython"));
31	            }
32	            out_flush();
33	            let real = matches!(v, V::Module(&ModName("sys.stdout")));
34	            STDOUT_SET.with(|s| *s.borrow_mut() = if real { None } else { Some(v) });
35	            Ok(())
36	        }
37	        _ => Err(unsupported(&format!("assigning sys.{name}"))),
38	    }
39	}
40	pub fn out_write(t: &str) {
41	    // CPython's text streams on Windows write CRLF; match them (every LF, as its TextIOWrapper does).
42	    #[cfg(windows)]
43	    let t = t.replace('\n', "\r\n");
44	    #[cfg(windows)]
45	    let t = t.as_str();
46	    OUT.with(|o| {
47	        let mut o = o.borrow_mut();
48	        if o.buf.len() + t.len() > 8192 {
49	            let b = std::mem::take(&mut o.buf);
50	            std::io::stdout().write_all(&b).ok();
51	            if t.len() >= 8192 {
52	                std::io::stdout().write_all(t.as_bytes()).ok();
53	                std::io::stdout().flush().ok();
54	                return;
55	            }
56	        }
57	        o.buf.extend_from_slice(t.as_bytes());
58	        if o.tty && t.contains('\n') {
59	            let b = std::mem::take(&mut o.buf);
60	            std::io::stdout().write_all(&b).ok();
61	            std::io::stdout().flush().ok();
62	        }
63	    });
64	}
65	pub fn out_flush() {
66	    // try_with: a library value dropped by another thread-local's destructor at thread exit (a module CPython
67	    // runs, kept in sys.modules) flushes after OUT itself is gone, when there is nothing left to flush
68	    let _ = OUT.try_with(|o| {
69	        let mut o = o.borrow_mut();
70	        let b = std::mem::take(&mut o.buf);
71	        std::io::stdout().write_all(&b).ok();
72	        std::io::stdout().flush().ok();
73	    });
74	}
75	pub fn err_write(t: &str) {
76	    #[cfg(windows)]
77	    let t = t.replace('\n', "\r\n");
78	    #[cfg(windows)]
79	    let t = t.as_str();
80	    std::io::stderr().write_all(t.as_bytes()).ok();
81	}
82	fn with_stdin<T>(f: impl FnOnce(&mut std::io::BufReader<std::io::Stdin>) -> T) -> T {
83	    STDIN.with(|s| {
84	        let mut s = s.borrow_mut();
85	        if s.is_none() {
86	            *s = Some(std::io::BufReader::new(std::io::stdin()));
87	        }
88	        f(s.as_mut().unwrap())
89	    })
90	}
